window.BOOK={"key":"samawal","app":"mutoon-samawal","lsk":"mutoon_samawal_v1","prefix":"sa_","title":"لامية السموأل","sub":"الشعر العربي · السموأل بن عادياء (ت نحو ٦٥ ق.هـ) · ٢٣ بيتًا","poems":[{"id":"samawal","title":"لامية السموأل","nazim":"السموأل بن غريض بن عادياء (وتُنسب أيضًا لعبد الملك بن عبد الرحيم الحارثي)","death":"ت نحو ٦٥ ق.هـ","meter":"الطويل","source":"ويكي مصدر (نص الموسوعة الشعرية المشكول، وهو نص موقع الديوان): «إذا المرء لم يدنس من اللؤم عرضه»","srcUrl":"https://ar.wikisource.org/wiki/إذا_المرء_لم_يدنس_من_اللؤم_عرضه","note":"لامية السموأل في الفخر (٢٣ بيتًا)، من نص الموسوعة الشعرية المشكول (ويكي مصدر وموقع الديوان)، قوبلت كلمةً كلمةً بسكربت بمتن شرح ديوان الحماسة للمرزوقي (٢٢ بيتًا)، واعتُمد المتداول حيث اختلفت الروايات. أُكمل من الشكل ما يقتضيه اصطلاح المصدر، وفُحص وزن كل شطر، والتفصيل في تقرير المصادر.","verses":[["إِذَا الْمَرْءُ لَمْ يَدْنَسْ مِنَ اللُّؤْمِ عِرْضُهُ","فَكُلُّ رِدَاءٍ يَرْتَدِيهِ جَمِيلُ"],["وَإِنْ هُوَ لَمْ يَحْمِلْ عَلَى النَّفْسِ ضَيْمَهَا","فَلَيْسَ إِلَى حُسْنِ الثَّنَاءِ سَبِيلُ"],["تُعَيِّرُنَا أَنَّا قَلِيلٌ عَدِيدُنَا","فَقُلْتُ لَهَا إِنَّ الْكِرَامَ قَلِيلُ"],["وَمَا قَلَّ مَنْ كَانَتْ بَقَايَاهُ مِثْلَنَا","شَبَابٌ تَسَامَى لِلْعُلَى وَكُهُولُ"],["وَمَا ضَرَّنَا أَنَّا قَلِيلٌ وَجَارُنَا","عَزِيزٌ وَجَارُ الْأَكْثَرِينَ ذَلِيلُ"],["لَنَا جَبَلٌ يَحْتَلُّهُ مَنْ نُجِيرُهُ","مَنِيعٌ يَرُدُّ الطَّرْفَ وَهْوَ كَلِيلُ"],["رَسَا أَصْلُهُ تَحْتَ الثَّرَى وَسَمَا بِهِ","إِلَى النَّجْمِ فَرْعٌ لَا يُنَالُ طَوِيلُ"],["هُوَ الْأَبْلَقُ الْفَرْدُ الَّذِي شَاعَ ذِكْرُهُ","يَعِزُّ عَلَى مَنْ رَامَهُ وَيَطُولُ"],["وَإِنَّا لَقَوْمٌ لَا نَرَى الْقَتْلَ سُبَّةً","إِذَا مَا رَأَتْهُ عَامِرٌ وَسَلُولُ"],["يُقَرِّبُ حُبُّ الْمَوْتِ آجَالَنَا لَنَا","وَتَكْرَهُهُ آجَالُهُمْ فَتَطُولُ"],["وَمَا مَاتَ مِنَّا سَيِّدٌ حَتْفَ أَنْفِهِ","وَلَا طُلَّ مِنَّا حَيْثُ كَانَ قَتِيلُ"],["تَسِيلُ عَلَى حَدِّ الظُّبَاتِ نُفُوسُنَا","وَلَيْسَتْ عَلَى غَيْرِ الظُّبَاتِ تَسِيلُ"],["صَفَوْنَا فَلَمْ نَكْدُرْ وَأَخْلَصَ سِرَّنَا","إِنَاثٌ أَطَابَتْ حَمْلَنَا وَفُحُولُ"],["عَلَوْنَا إِلَى خَيْرِ الظُّهُورِ وَحَطَّنَا","لِوَقْتٍ إِلَى خَيْرِ الْبُطُونِ نُزُولُ"],["فَنَحْنُ كَمَاءِ الْمُزْنِ مَا فِي نِصَابِنَا","كَهَامٌ وَلَا فِينَا يُعَدُّ بَخِيلُ"],["وَنُنْكِرُ إِنْ شِئْنَا عَلَى النَّاسِ قَوْلَهُمْ","وَلَا يُنْكِرُونَ الْقَوْلَ حِينَ نَقُولُ"],["إِذَا سَيِّدٌ مِنَّا خَلَا قَامَ سَيِّدٌ","قَؤُولٌ لِمَا قَالَ الْكِرَامُ فَعُولُ"],["وَمَا أُخْمِدَتْ نَارٌ لَنَا دُونَ طَارِقٍ","وَلَا ذَمَّنَا فِي النَّازِلِينَ نَزِيلُ"],["وَأَيَّامُنَا مَشْهُورَةٌ فِي عَدُوِّنَا","لَهَا غُرَرٌ مَعْلُومَةٌ وَحُجُولُ"],["وَأَسْيَافُنَا فِي كُلِّ شَرْقٍ وَمَغْرِبٍ","بِهَا مِنْ قِرَاعِ الدَّارِعِينَ فُلُولُ"],["مُعَوَّدَةٌ أَلَّا تُسَلَّ نِصَالُهَا","فَتُغْمَدَ حَتَّى يُسْتَبَاحَ قَبِيلُ"],["سَلِي إِنْ جَهِلْتِ النَّاسَ عَنَّا وَعَنْهُمُ","فَلَيْسَ سَوَاءً عَالِمٌ وَجَهُولُ"],["فَإِنَّ بَنِي الدَّيَّانِ قَطْبٌ لِقَوْمِهِمْ","تَدُورُ رَحَاهُمْ حَوْلَهُمْ وَتَجُولُ"]],"secs":{"1":"لامية السموأل"}}],"sharh":false};
